    g=np.linspace(-4,4,401)
    vals=[]
    for v in g:
        y=base.copy(); y[t]=v
        vals.append(acts(y.reshape(1,10))['h%d'%(t+1)][0,j])
    vals=np.array(vals)
    # find where vals crosses 0 upward
    b=[]
    for k in range(len(g)-1):
        if vals[k]<=1e-12 and vals[k+1]>1e-12:
            b.append(round(g[k+1],3))
        if vals[k]>1e-12 and vals[k+1]<=1e-12:
            b.append(round(g[k+1],3))
    return b
